<?php
require_login();
$u=user();
$cid=(int)$u['company_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    check_csrf();
    $action=(string)($_POST['support_action']??'create');
    if($action==='create'){
        $subject=trim((string)($_POST['subject']??'')); $category=trim((string)($_POST['category']??'bug')); $priority=trim((string)($_POST['priority']??'normal')); $message=trim((string)($_POST['message']??''));
        $allowedCat=['bug','feedback','feature','billing','other']; $allowedPri=['low','normal','high','urgent'];
        if($subject===''||$message===''){flash('error','Subject and message are required.');redirect('support');}
        if(!in_array($category,$allowedCat,true))$category='bug'; if(!in_array($priority,$allowedPri,true))$priority='normal';
        db()->prepare('INSERT INTO support_tickets(company_id,user_id,subject,category,message,priority,status) VALUES(?,?,?,?,?,? ,"open")')->execute([$cid,$u['id'],$subject,$category,$message,$priority]);
        flash('success','Your feedback/support ticket has been submitted.'); redirect('support');
    }
}
$st=db()->prepare('SELECT id,subject,category,priority,status,message,admin_reply,created_at,updated_at FROM support_tickets WHERE company_id=? ORDER BY id DESC LIMIT 100');$st->execute([$cid]);$tickets=$st->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Support & Feedback · <?=e($u['company_name'])?></title><link rel="stylesheet" href="<?=e(url('assets/app.css'))?>?v=125"></head><body><div class="app-shell"><main class="main" style="width:100%"><header class="topbar"><div class="searchbar"><span>⌕</span><span style="font-size:14px">Support & Feedback</span></div><div class="top-actions"><a class="btn" href="<?=e(url('dashboard'))?>">← Dashboard</a><a class="gear" href="<?=e(url('logout'))?>">Logout</a></div></header><div class="content"><div class="page-title"><div><h1>Support & Feedback</h1><p>Report a bug, send feedback, or request a feature.</p></div></div><div class="grid2"><div class="panel"><div class="panel-head"><h2>New Request</h2></div><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="support_action" value="create"><div class="form-group"><label>Subject*</label><input name="subject" required></div><div class="grid2"><div class="form-group"><label>Category</label><select name="category"><option value="bug">Bug / Problem</option><option value="feedback">Feedback</option><option value="feature">Feature Request</option><option value="billing">Billing</option><option value="other">Other</option></select></div><div class="form-group"><label>Priority</label><select name="priority"><option value="normal">Normal</option><option value="low">Low</option><option value="high">High</option><option value="urgent">Urgent</option></select></div></div><div class="form-group"><label>Message*</label><textarea name="message" rows="8" required placeholder="Describe the problem, steps to reproduce, or your feedback."></textarea></div><button class="btn primary">Send Request</button></form></div><div class="panel"><div class="panel-head"><h2>My Requests</h2><span class="status paid"><?=count($tickets)?> total</span></div><div class="support-list"><?php foreach($tickets as $t):?><div class="support-ticket"><div class="support-ticket-head"><strong>#<?=e((string)$t['id'])?> · <?=e($t['subject'])?></strong><span class="status <?=in_array($t['status'],['closed','resolved'],true)?'paid':'due'?>"><?=e(ucfirst($t['status']))?></span></div><div class="subtle"><?=e(ucfirst($t['category']))?> · <?=e(ucfirst($t['priority']))?> · <?=e($t['created_at'])?></div><div class="support-message"><?=nl2br(e($t['message']))?></div><?php if(trim((string)$t['admin_reply'])!==''):?><div class="support-reply"><b>Support reply</b><div><?=nl2br(e($t['admin_reply']))?></div></div><?php endif;?></div><?php endforeach;if(!$tickets):?><div class="subtle">No requests yet.</div><?php endif;?></div></div></div></div></main></div><style>.support-list{display:flex;flex-direction:column;gap:10px}.support-ticket{border:1px solid #dde4ee;border-radius:10px;padding:12px;background:#fff}.support-ticket-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.support-message{margin-top:9px;white-space:normal;color:#34445c;font-size:13px;line-height:1.5}.support-reply{margin-top:10px;padding:10px;background:#f4fbf7;border-left:3px solid #10b981;border-radius:6px;color:#2f4b3d;font-size:13px}.support-reply b{display:block;margin-bottom:4px}</style></body></html>
